ids = [101, 102, 103]
amounts = [250.0, -40.0, 0.0]

results = []
for i, (txn_id, amount) in enumerate(zip(ids, amounts)):
    if amount > 0:
        kind = "credit"
    elif amount < 0:
        kind = "debit"
    else:
        kind = "zero"
    results.append({"row": i, "id": txn_id, "kind": kind})

for r in results:
    print(r)

def fetch_page(n):
    # Mock: pages 1..3 have data, page 4 is the last (empty)
    data = {1: ["a", "b"], 2: [], 3: ["c"]}
    return data.get(n, None)

page = 1
all_rows = []
MAX_PAGES = 100  # safety guard against infinite loops
while page <= MAX_PAGES:
    rows = fetch_page(page)
    if rows is None:
        print("No more pages; stopping.")
        break
    page += 1
    if not rows:            # empty page -> skip
        continue
    all_rows.extend(rows)
else:
    print("Hit MAX_PAGES guard without a natural stop.")

print(all_rows)
